        async fn record_orchestration_event(
            &self,
            request: Request<pb::RecordOrchestrationEventRequest>,
        ) -> Result<Response<pb::RecordOrchestrationEventResponse>, Status> {
            if let Some(rules) = rules_of(&self.rec) {
                let caller = crate::runtime_loop::session_core_rules_double::caller_of(&request)?;
                return rules
                    .record_orchestration_event(&caller, request.into_inner())
                    .map(Response::new);
            }
            match request.into_inner().event {
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::PlanTransitioned(pt)),
                    ..
                }) => {
                    self.rec
                        .lock()
                        .unwrap()
                        .plan_transitions
                        .push((pt.from, pt.to));
                }
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::SubagentStopped(stopped)),
                    ..
                }) => {
                    self.rec.lock().unwrap().stopped_children.push((
                        stopped.parent_run_id,
                        stopped.child_run_id,
                        stopped.status,
                    ));
                }
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::RunParked(parked)),
                    ..
                }) => {
                    self.rec.lock().unwrap().run_parked_events.push(parked.run_id);
                }
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::RunResumed(resumed)),
                    ..
                }) => {
                    let mut rec = self.rec.lock().unwrap();
                    rec.order.push("run_resumed".to_owned());
                    rec.run_resumed_events
                        .push((resumed.run_id, resumed.resumed_segment));
                }
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::RunUsageProgress(progress)),
                    ..
                }) => {
                    self.rec.lock().unwrap().run_usage_progress.push(progress);
                }
                Some(pb::OrchestrationEvent {
                    event: Some(pb::orchestration_event::Event::ToolRetryScheduled(retry)),
                    ..
                }) => {
                    self.rec.lock().unwrap().tool_retries.push(retry);
                }
                _ => {}
            }
            Ok(Response::new(pb::RecordOrchestrationEventResponse {
                event_id: "evt".to_owned(),
            }))
        }

