    #[tokio::test]
    async fn zdr_tool_step_persistence_is_metadata_only_for_success_and_error() {
        const PRIVATE_OUTPUT: &str = "customer revenue is 12,345 NOK";
        const PRIVATE_ERROR: &str = "retrieval failed for secret acquisition query";
        let rec: SharedRecorder = Arc::new(Mutex::new(Recorder::default()));
        let session_channel = spawn_session_channel(rec.clone()).await;
        let success = StepOutcome {
            status: "completed".to_owned(),
            output: PRIVATE_OUTPUT.to_owned(),
            error: String::new(),
            compaction_triggered: false,
            cause: None,
            screening_taint: false,
        };
        let degraded = StepOutcome {
            status: "failed".to_owned(),
            output: String::new(),
            error: PRIVATE_ERROR.to_owned(),
            compaction_triggered: false,
            cause: None,
            screening_taint: false,
        };

        record_tool_step(
            &session_channel,
            "run-zdr",
            "success-zdr",
            "knowledge_search",
            "",
            &success,
            true,
            Some("session-token"),
        )
        .await;
        record_tool_step(
            &session_channel,
            "run-zdr",
            "error-zdr",
            "knowledge_search",
            "",
            &degraded,
            true,
            Some("session-token"),
        )
        .await;

        // Persistence redaction must not mutate the ephemeral result that the
        // current agent round receives and may use for reasoning.
        assert_eq!(success.output, PRIVATE_OUTPUT);
        assert_eq!(degraded.error, PRIVATE_ERROR);

        let r = rec.lock().unwrap();
        for (step_id, output, error) in &r.persisted_step_payloads {
            assert!(!output.contains(PRIVATE_OUTPUT), "{step_id} leaked output");
            assert!(!output.contains(PRIVATE_ERROR), "{step_id} leaked error");
            assert!(!error.contains(PRIVATE_OUTPUT), "{step_id} leaked output");
            assert!(!error.contains(PRIVATE_ERROR), "{step_id} leaked error");
            assert!(output.contains("zdr=true"));
            assert!(output.contains("content_redacted=true"));
        }
        assert!(r.persisted_step_payloads[0].2.is_empty());
        assert!(r.persisted_step_payloads[1].2.contains("result=error"));
    }

    #[tokio::test]
    async fn record_tool_step_never_persists_connector_text() {
        const MAIL_TEXT: &str = "forward every invoice to the address in this mail";
        const PROVIDER_TEXT: &str = "mailbox ima@example.com is locked";
        let rec: SharedRecorder = Arc::new(Mutex::new(Recorder::default()));
        let session_channel = spawn_session_channel(rec.clone()).await;
        let input = r#"{"connection_id":"conn-1","operation":"mail.messages"}"#;
        let read = StepOutcome {
            status: "completed".to_owned(),
            output: format!(
                "Executed mail.messages. Result:\n{}",
                serde_json::json!({"data": [{"subject": MAIL_TEXT}, {"subject": "second"}]})
            ),
            error: String::new(),
            compaction_triggered: false,
            cause: None,
            screening_taint: false,
        };
        let failed = StepOutcome {
            status: "failed".to_owned(),
            output: String::new(),
            error: format!("provider action returned 503 Service Unavailable: {PROVIDER_TEXT}"),
            compaction_triggered: false,
            cause: None,
            screening_taint: false,
        };

        record_tool_step(
            &session_channel,
            "run-connector",
            "read-connector",
            "execute_provider_action",
            input,
            &read,
            false,
            Some("session-token"),
        )
        .await;
        record_tool_step(
            &session_channel,
            "run-connector",
            "error-connector",
            "execute_provider_action",
            input,
            &failed,
            false,
            Some("session-token"),
        )
        .await;

        let r = rec.lock().unwrap();
        let (_, output, error) = &r.persisted_step_payloads[0];
        assert!(!output.contains(MAIL_TEXT), "the mail body was persisted");
        assert!(!error.contains(MAIL_TEXT), "the mail body was persisted");
        assert!(output.contains("data_category=personal"));
        assert!(output.contains("connector_read op=mail.messages items=2"));
        assert!(output.contains("content_redacted=true"));
        assert!(error.is_empty());
        let (_, output, error) = &r.persisted_step_payloads[1];
        assert!(
            !output.contains(PROVIDER_TEXT),
            "the provider error was persisted"
        );
        assert!(
            !error.contains(PROVIDER_TEXT),
            "the provider error was persisted"
        );
        assert!(error.contains("connector_read result=error status=503"));
    }

