    #[tokio::test]
    async fn plan_propose_dispatches_even_while_plan_mode_blocks_risky_tools() {
        // plan-gate §2.1: `plan.propose` is the plan-mode run's own way of
        // acting -- it must dispatch normally even though plan mode refuses
        // every risky/destructive tool at this same call site (the test right
        // above this one), because `plan.propose` is read-only from the
        // run's own permission-ladder point of view: it is never matched by
        // `permission::is_risky_call`/`is_restricted_context_write`, so the
        // plan-mode refusal in the call loop never fires for it.
        let rec: SharedRecorder = Arc::new(Mutex::new(Recorder::default()));
        let session_channel = spawn_session_channel(rec.clone()).await;
        let inference_channel = spawn_inference_channel(vec![
            Scripted::ToolCalls {
                content: String::new(),
                calls: vec![pb::ToolCall {
                    id: "propose-1".to_owned(),
                    name: "plan.propose".to_owned(),
                    arguments_json: serde_json::json!({
                        "summary": "Send the overdue invoice",
                        "steps": [
                            {"title": "Draft the email"},
                            {"title": "Send it", "operation": "email_send"},
                        ],
                    })
                    .to_string(),
                }],
            },
            Scripted::Answer("I've proposed a plan for your review.".to_owned()),
        ])
        .await;
        let state = crate::state::StateStore::new();

        let mut req = sample_request();
        req.mode = "auto".to_owned();
        req.plan_mode = true;
        // Exactly what the gateway sends for a plan-mode run (`sse.rs`:
        // "a plan-mode run is held to READ_ONLY"). Without this the graded
        // rung check (`check_autonomy_rung`) is skipped as "no rung stated",
        // and the test would pass even if `plan.propose` were classified as
        // needing a wider rung than the one plan mode holds.
        req.autonomy_rung = pb::AutonomyRung::ReadOnly as i32;
        // `run_agent_with_tools` (unlike the public `run_agent`) takes an
        // EXPLICIT injected tool set as the purpose-lock allowlist — it does
        // not call `offered_tool_defs()` itself (see its own doc comment) —
        // so the tool under test must be listed here, the same way the
        // sibling risky-tool test above lists `delete_records`.
        let plan_tools = vec![pb::ToolDefinition {
            name: crate::plan::PROPOSE_TOOL.to_owned(),
            description: String::new(),
            parameters_json: "{}".to_owned(),
        }];
        let resp = run_agent_with_tools(
            &state,
            session_channel,
            inference_channel,
            &plain_caller(),
            req,
            plan_tools,
            None,
            Some("session-token".to_owned()),
            "inference-token".to_owned(),
            &ALLOW_CAPABILITY_POLICY,
            &STATIC_TERMINAL_TOKENS,
            None,
            None,
            &test_sandbox_manager_client(),
            "test-backend",
            None,
            &test_sandbox_tokens(),
            None,
        )
        .await
        .expect("plan.propose must dispatch and the run must complete");

        assert_eq!(resp.status, "completed");
        assert_eq!(
            resp.final_output,
            "I've proposed a plan for your review."
        );

        let r = rec.lock().unwrap();
        assert_eq!(
            r.propose_plan_calls,
            vec![(
                "thread_test".to_owned(),
                "Send the overdue invoice".to_owned(),
                2
            )],
            "plan.propose must reach session-core's ProposePlan with the model's summary and step count"
        );
    }

    /// One `ask_user` call with a single question of two choices, as the model writes it.
    fn ask_user_call(id: &str, question_id: &str) -> pb::ToolCall {
        pb::ToolCall {
            id: id.to_owned(),
            name: "ask_user".to_owned(),
            arguments_json: serde_json::json!({
                "questions": [{
                    "id": question_id,
                    "kind": "single",
                    "prompt": "Which carrier should I book?",
                    "options": [
                        {"id": "bring", "label": "Bring"},
                        {"id": "postnord", "label": "PostNord"},
                    ],
                    "allow_other": false,
                }],
            })
            .to_string(),
        }
    }

    /// A Do run whose first round makes `calls`, with `max_questions` on its request and the tool
    /// injected as the purpose-lock allowlist, as the plan test injects `plan.propose`.
    async fn ask_user_run(
        calls: Vec<pb::ToolCall>,
        max_questions: u32,
    ) -> (Result<pb::RunAgentResponse, tonic::Status>, SharedRecorder) {
        let rec: SharedRecorder = Arc::new(Mutex::new(Recorder::default()));
        let session_channel = spawn_session_channel(rec.clone()).await;
        let inference_channel = spawn_inference_channel(vec![
            Scripted::ToolCalls {
                content: String::new(),
                calls,
            },
            Scripted::Answer("I will continue once you answer.".to_owned()),
        ])
        .await;
        let state = crate::state::StateStore::new();
        let mut req = sample_request();
        req.mode = "auto".to_owned();
        req.max_questions = max_questions;
        let tools = vec![pb::ToolDefinition {
            name: "ask_user".to_owned(),
            description: String::new(),
            parameters_json: "{}".to_owned(),
        }];
        let resp = run_agent_with_tools(
            &state,
            session_channel,
            inference_channel,
            &plain_caller(),
            req,
            tools,
            None,
            Some("session-token".to_owned()),
            "inference-token".to_owned(),
            &ALLOW_CAPABILITY_POLICY,
            &STATIC_TERMINAL_TOKENS,
            None,
            None,
            &test_sandbox_manager_client(),
            "test-backend",
            None,
            &test_sandbox_tokens(),
            None,
        )
        .await;
        (resp, rec)
    }

    #[tokio::test]
    async fn ask_user_ends_the_turn_with_the_question_and_stores_it_once() {
        let _switch = crate::runtime_loop::ask::test_switch::force(true);
        let (resp, rec) = ask_user_run(vec![ask_user_call("ask-1", "carrier")], 3).await;
        let resp = resp.expect("ask_user must dispatch and the run must complete");

        assert_eq!(resp.status, "completed");
        assert!(
            resp.final_output.contains("Which carrier should I book?")
                && resp.final_output.contains("- Bring"),
            "the turn answers with the question as prose: {}",
            resp.final_output
        );
        let r = rec.lock().unwrap();
        assert_eq!(r.run_questions.len(), 1, "one question is stored");
        let stored = &r.run_questions[0];
        assert_eq!(stored.delivery, "next_turn");
        assert_eq!(stored.items[0].id, "carrier");
        assert!(!stored.run_id.is_empty() && !stored.step_id.is_empty());
        assert_eq!(
            stored.idempotency_key,
            format!("{}:{}", stored.run_id, stored.step_id),
            "a retry of the same step returns the question it stored"
        );
    }

    #[tokio::test]
    async fn the_fourth_question_of_a_run_is_refused_and_stores_nothing() {
        let _switch = crate::runtime_loop::ask::test_switch::force(true);
        let calls = (1..=4)
            .map(|n| ask_user_call(&format!("ask-{n}"), &format!("q{n}")))
            .collect();
        let (resp, rec) = ask_user_run(calls, 3).await;
        let resp = resp.expect("the run completes");

        assert_eq!(resp.status, "completed");
        assert_eq!(
            rec.lock().unwrap().run_questions.len(),
            3,
            "the run's cap of three holds: the fourth call stores nothing"
        );
    }

    #[tokio::test]
    async fn with_the_switch_off_a_question_call_is_refused_and_the_run_goes_on() {
        let _switch = crate::runtime_loop::ask::test_switch::force(false);
        let (resp, rec) = ask_user_run(vec![ask_user_call("ask-1", "carrier")], 3).await;
        let resp = resp.expect("the run completes");

        assert_eq!(resp.status, "completed");
        assert_eq!(resp.final_output, "I will continue once you answer.");
        assert!(rec.lock().unwrap().run_questions.is_empty());
    }

    #[tokio::test]
    async fn subagent_honors_a_requested_budget_and_reports_exhaustion_honestly() {
        let rec: SharedRecorder = Arc::new(Mutex::new(Recorder::default()));
        let session_channel = spawn_session_channel(rec.clone()).await;

        // A one-round subagent that spends that round on a tool call cannot
        // answer. The parent must be told so, not handed a fake result.
        let observed_messages: ObservedMessages = Arc::new(Mutex::new(Vec::new()));
        let inference_channel = spawn_inference_channel_with_messages(
            vec![
                Scripted::ToolCalls {
                    content: String::new(),
                    calls: vec![subagent_call(
                        "sub-b",
                        r#"{"goal":"deep research","max_rounds":1}"#,
                    )],
                },
                Scripted::ToolCalls {
                    content: String::new(),
                    calls: vec![failing_tool_call("wx-1")],
                },
                Scripted::Answer("The delegated lookup did not finish.".to_owned()),
            ],
            observed_messages.clone(),
        )
        .await;
        let state = crate::state::StateStore::new();

        let resp = run_agent(
            &state,
            session_channel,
            inference_channel,
            &plain_caller(),
            sample_request(),
            None,
            Some("session-token".to_owned()),
            "inference-token".to_owned(),
            &ALLOW_CAPABILITY_POLICY,
            &STATIC_TERMINAL_TOKENS,
            None,
            None,
            None,
            &test_sandbox_manager_client(),
            "test-backend",
            None,
            &test_sandbox_tokens(),
            None,
            crate::knowledge_tools::SpaceRetrieval::Organisation,
        )
        .await
        .expect("a failed delegation must not fail the parent run");

        assert_eq!(resp.status, "completed");
        assert_eq!(resp.final_output, "The delegated lookup did not finish.");
        assert_eq!(
            observed_messages.lock().unwrap().len(),
            3,
            "the subagent got exactly the 1 round it asked for, not the default 12"
        );

        let r = rec.lock().unwrap();
        let (output, error) = persisted_step(&r, "tool_1_sub-b");
        assert!(
            error.contains("1-round budget"),
            "the parent is told the real budget that ran out: {error}"
        );
        assert_eq!(
            output.trim_end(),
            "[data_category=customer_private zdr=false tool=subagent.task]",
            "an exhausted subagent contributes audit metadata only — never a result"
        );
    }

    /// What one inference response reports, for the tally's own table.
    fn round_response(
        input: i32,
        output: i32,
        cache_read: i32,
        cache_creation: i32,
        provider: &str,
        model: &str,
    ) -> pb::InferResponse {
        pb::InferResponse {
            input_tokens: input,
            output_tokens: output,
            cache_read_input_tokens: cache_read,
            cache_creation_input_tokens: cache_creation,
            provider_used: provider.to_owned(),
            model_used: model.to_owned(),
            ..Default::default()
        }
    }

    #[test]
    fn the_tally_sums_every_round_and_keeps_one_leg_per_provider_and_model() {
        let tally = UsageTally::default();
        assert_eq!(
            tally.snapshot(),
            pb::RunUsage::default(),
            "no round yet is zero rounds, not an absent count"
        );
        tally.record(&round_response(100, 10, 60, 20, "anthropic", "model-a"));
        // A shared handle (a delegated child's clone) adds to the same tally.
        let child = tally.clone();
        child.record(&round_response(50, 5, 0, 0, "", ""));
        // A provider's negative count never subtracts from the run.
        tally.record(&round_response(-7, -7, -7, -7, "openai", "model-b"));
        // A second round on a route already seen adds to that route's leg.
        tally.record(&round_response(10, 1, 5, 0, "anthropic", "model-a"));
        let leg = |provider: &str, model: &str, input, output, read, creation, rounds| {
            pb::RunUsageLeg {
                provider_used: provider.to_owned(),
                model_used: model.to_owned(),
                input_tokens: input,
                output_tokens: output,
                cache_read_input_tokens: read,
                cache_creation_input_tokens: creation,
                inference_rounds: rounds,
            }
        };
        assert_eq!(
            tally.snapshot(),
            pb::RunUsage {
                input_tokens: 160,
                output_tokens: 16,
                cache_read_input_tokens: 65,
                cache_creation_input_tokens: 20,
                inference_rounds: 4,
                // The leg that served the most rounds names the totals.
                provider_used: "anthropic".to_owned(),
                model_used: "model-a".to_owned(),
                // Provider then model order; a round that named neither is its own leg.
                legs: vec![
                    leg("", "", 50, 5, 0, 0, 1),
                    leg("anthropic", "model-a", 110, 11, 65, 20, 2),
                    leg("openai", "model-b", 0, 0, 0, 0, 1),
                ],
            },
        );
    }

    /// Concurrent delegates record in whatever order they finish. The legs, the
    /// totals and the route they name must not depend on it, or the envelope keys
    /// (`-AGENT_USAGE-{n}`) would move between a retry and the first publish.
    #[test]
    fn the_legs_do_not_depend_on_which_delegate_recorded_first() {
        let rounds = [
            round_response(10, 1, 0, 0, "openai", "model-b"),
            round_response(20, 2, 5, 0, "anthropic", "model-a"),
            round_response(30, 3, 0, 5, "anthropic", "model-c"),
            round_response(40, 4, 0, 0, "openai", "model-b"),
            round_response(50, 5, 0, 0, "anthropic", "model-a"),
            round_response(60, 6, 0, 0, "azure", "router"),
        ];
        let count = rounds.len();
        let sequential = UsageTally::default();
        for round in &rounds {
            sequential.record(round);
        }
        for shuffle in 0..4 {
            let tally = UsageTally::default();
            let handles: Vec<_> = rounds
                .iter()
                .enumerate()
                .map(|(index, round)| {
                    let (tally, round) = (tally.clone(), round.clone());
                    std::thread::spawn(move || {
                        // Different starts per run reorder the recordings.
                        std::thread::sleep(std::time::Duration::from_millis(
                            ((index + shuffle * 2) % count) as u64 * 3,
                        ));
                        tally.record(&round);
                    })
                })
                .collect();
            for handle in handles {
                handle.join().expect("a recording thread");
            }
            assert_eq!(tally.snapshot(), sequential.snapshot(), "shuffle {shuffle}");
        }
        let snapshot = sequential.snapshot();
        assert_eq!(
            snapshot
                .legs
                .iter()
                .map(|leg| (leg.provider_used.as_str(), leg.model_used.as_str()))
                .collect::<Vec<_>>(),
            [
                ("anthropic", "model-a"),
                ("anthropic", "model-c"),
                ("azure", "router"),
                ("openai", "model-b"),
            ]
        );
        // Two legs served two rounds; the first of them in order names the totals.
        assert_eq!(
            (snapshot.provider_used.as_str(), snapshot.model_used.as_str()),
            ("anthropic", "model-a")
        );
        assert_eq!(snapshot.inference_rounds, 6);
        assert_eq!(snapshot.input_tokens, 210);
    }

